})

Translate("zhCN", "marshal-maxwell", {
	title = "麦克斯韦尔元帅",
	subtitle = "摩根的岗哨指挥官",
	found = "平原东南部的摩根的岗哨",
	hint = "与坚守暴风城在燃烧平原上最后一道山脊的元帅交谈。",
	allegiance = "暴风王国 · 暴风城军队",
	aliases = { "麦克斯韦尔" },
	sections = {
		{
